// The model this run of the lab uses: 'E143' by default, or OM_EMU_MODEL in the environment / ?model= in a Worker URL.
// A(address) translates an E143 firmware or scratch address to the model's build through PORTS (src/fw/ports.mjs,
// generated by bin/port.mjs). UNMAPPED(address) stands for an E143 address the port could not place in the model's
// build: it is an address no region maps (0xFE000000 | its low 24 bits), and refuseUnmapped() makes the lab's hooks and
// calls refuse it, so a missing address fails where it is first used instead of hooking nothing.
import { MODELS } from './models.mjs';
import { PORTS, FACTS, KNOBS } from './ports.mjs';
import { valueAt } from './facts.mjs';

const envModel = globalThis.OM_EMU_MODEL ?? Reflect.get(globalThis, 'process')?.env?.OM_EMU_MODEL
  ?? (typeof location !== 'undefined' ? new URLSearchParams(location.search).get('model') : null);
// LAB_MODEL: the build the lab is written against (every address in src/lab, the hand lists beside them and the E143
// values given at a fact()'s use); ON_LAB_MODEL: this run is on it. A check of the image against such a hand list
// (src/lab/osd.mjs mm_ctors, src/lab/camapp.mjs module_queues, ...) runs ON_LAB_MODEL only: on another model the
// list is E143's, not the model's.
export const LAB_MODEL = 'E143';
export const MODEL = envModel || LAB_MODEL, ON_LAB_MODEL = MODEL === LAB_MODEL;
if (!Object.hasOwn(MODELS, MODEL)) throw new Error(`unknown model ${JSON.stringify(MODEL)} (choose from ${Object.keys(MODELS).join(', ')})`);
export const MODEL_INFO = MODELS[MODEL];
// The run-time copy of the main block (MODELS image_base): byte 0 of the run-time image at IMAGE_BASE, the block's
// code up to IMAGE_END (E143: 0x60021020..0x62020FE0); the disassembly notation is 0x50000000 + the same offset.
if (!Number.isInteger(MODEL_INFO.image_base)) throw new Error(`${MODEL}: src/fw/models.mjs gives no image_base (src/fw/facts.mjs imageBase reads it from the block)`);
export const IMAGE_BASE = MODEL_INFO.image_base >>> 0, IMAGE_END = (IMAGE_BASE + MODEL_INFO.rom_len) >>> 0;
export const UNMAPPED = (address) => (0xFE000000 | (address & 0xFFFFFF)) >>> 0;
export const isUnmapped = (address) => ((address >>> 24) & 0xFF) === 0xFE;
const PORT = ON_LAB_MODEL ? null : PORTS[MODEL] ?? null;
export function A(address) {
  const v = address >>> 0;
  if (!PORT) return v;
  const to = PORT[v];
  return to === undefined ? v : to === null ? UNMAPPED(v) : to >>> 0;
}
// A per-model fact the lab needs besides an address: E143's own value (`e143`, given at the use with its evidence) on
// E143, and on another model the value at `path` ('res.font_limit') that bin/port.mjs read from its firmware
// (src/fw/ports.mjs FACTS[MODEL]) or that its MODELS entry gives by hand with its evidence. There is no default: a
// model without the fact throws where the lab first needs it, and one with it both ways throws too.
export function fact(path, e143) {
  if (ON_LAB_MODEL) return e143;
  const read = valueAt(FACTS[MODEL], path), hand = valueAt(MODEL_INFO, path);
  if (read !== undefined && hand !== undefined) throw new Error(`${MODEL}: ${path} is both read from the firmware (src/fw/ports.mjs FACTS) and given by hand (src/fw/models.mjs)`);
  if (read === undefined && hand === undefined) throw new Error(`${MODEL}: neither src/fw/ports.mjs FACTS nor src/fw/models.mjs gives ${path} (E143's is ${typeof e143 === 'object' ? JSON.stringify(e143) : e143})`);
  return read ?? hand;
}
// (the sentinel keeps the low 24 bits only: the E143 address is the unplaced entry of PORTS with them)
export function refuseUnmapped(address, what) {
  if (!isUnmapped(address)) return;
  const low = address & 0xFFFFFF, hex = (v) => '0x' + (v >>> 0).toString(16).padStart(8, '0');
  const e143 = Object.keys(PORT ?? {}).map(Number).filter((k) => PORT[k] === null && (k & 0xFFFFFF) === low);
  throw new Error(`${what}: the E143 address ${e143.map(hex).join(' or ') || hex(low)} has no place in ${MODEL}'s build (emu/out/port/${MODEL}/port.json)`);
}
// A MODELS knob (src/fw/knobs.mjs: one that holds firmware addresses): the model's own value (src/fw/models.mjs), or
// the one bin/port.mjs carried from its reference (src/fw/ports.mjs KNOBS, MODELS port_via and carry), or `dflt` when
// it has neither (E143's case: the lab's own value at the use). Given both ways throws.
export function knob(name, dflt) {
  const hand = MODEL_INFO[name], carried = KNOBS[MODEL]?.[name];
  if (hand !== undefined && carried !== undefined) throw new Error(`${MODEL}: ${name} is both carried (src/fw/ports.mjs KNOBS) and given by hand (src/fw/models.mjs)`);
  return hand ?? carried ?? dflt;
}
